% =========================================================================
% 03_nr_attack_rules.pl
% NR-Specific Datalog Predicate Library for 5G RAN Attack Graph Generation
%
% Inference model: forward-chaining (SWI-Prolog)
% Association model: distance-based (uniform RSRP; UE selects closest cell)
%
% Usage (standalone):
%   swipl -g "consult('facts.pl'), consult('03_nr_attack_rules.pl'),
%              run_all, halt."
%
% Usage (from Python via subprocess):
%   swipl -g "run_all, halt" -l facts.pl 03_nr_attack_rules.pl
%
% Primitive facts expected from facts.pl (generated by 02_extract_facts.py):
%   gnb(G)                    — G is a legitimate gNB cell ID
%   fbs(F)                    — F is an FBS cell ID
%   ue(U)                     — U is a benign UE ID
%   mue(M)                    — M is a MUE ID (synthetic label)
%   dist_to_cell(U, C, D)     — Distance D (m) from UE U to cell C
%   observed_fbs_assoc(U, F)  — Ground-truth: UE U attached to FBS F
%   observed_gnb_assoc(U, G)  — UE U attached to legitimate gNB G
%   high_contention_gnb(G)    — gNB G has RACH failure rate > threshold
%   mue_targets(M, G)         — MUE M floods PRACH at gNB G
%   rach_config(G, PMAX, NOCC)— gNB G has preambleTransMax=PMAX, NOCC slots
%   flood_rate(M, R)          — MUE M sends R fake preambles per occasion
% =========================================================================

:- use_module(library(lists)).
:- discontiguous gnb/1, fbs/1, ue/1, mue/1.
:- discontiguous dist_to_cell/3, observed_fbs_assoc/2, observed_gnb_assoc/2.
:- discontiguous high_contention_gnb/1, mue_targets/2.
:- discontiguous rach_config/3, flood_rate/2.


% =========================================================================
% TIER B: VULNERABILITY PREDICATES
% Root enabling conditions that the attacker exploits.
% Both hold unconditionally for all (UE, cell) pairs in 5G NR.
% =========================================================================

% no_cell_auth(U, F)
% 5G NR cell selection (3GPP TS 38.331 §5.2.3.3) is driven solely by
% RSRP/RSRQ of the SSB/SIB1 broadcast.  No cryptographic gNB identity
% verification occurs at the MAC layer.  Any node broadcasting valid SIB1
% is indistinguishable from a legitimate gNB during cell selection.
no_cell_auth(U, F) :-
    ue(U), fbs(F).

% prach_unprotected(G)
% PRACH Msg1 preambles (TS 38.211/38.213) carry no integrity protection.
% Any transmitter may inject arbitrary preamble sequences into any RACH
% occasion slot.  Holds for all gNBs.
prach_unprotected(G) :-
    gnb(G).


% =========================================================================
% TIER C: FBS ATTACK CHAIN — protocol-level exploit
% Association is distance-based: UE selects the closest cell (gNB or FBS)
% because RSRP is modelled as uniform across all transmitters.
% =========================================================================

% closest_cell_is_fbs(U, F)
% FBS F is the closest cell to UE U — i.e., no legitimate gNB G has a
% strictly shorter distance to U than F does.
% (RSRP uniform → distance determines cell selection, TS 38.331 §5.2.3.3)
closest_cell_is_fbs(U, F) :-
    fbs(F), ue(U),
    dist_to_cell(U, F, DF),
    \+ ( gnb(G), dist_to_cell(U, G, DG), DG < DF ).

% ue_selects_fbs(U, F)
% UE U selects FBS F as its serving cell.
% Derived via two routes:
%   (a) Distance-based derivation: FBS is closest AND no cell auth.
%   (b) Direct observation from ground-truth label in the CSV.
% The observed fact route is used when running against real simulation data;
% the distance-derivation route is used for forward prediction on new configs.
ue_selects_fbs(U, F) :-
    closest_cell_is_fbs(U, F),
    no_cell_auth(U, F).

ue_selects_fbs(U, F) :-        % observed ground-truth route
    observed_fbs_assoc(U, F).

% rach_to_fbs(U, F)
% UE U initiates the RACH procedure (Msg1→Msg2→Msg3→Msg4) toward FBS F,
% believing F to be a legitimate gNB.
% Corresponds to step (i) of the FBS event sequence in §Attack_Model.
rach_to_fbs(U, F) :-
    ue_selects_fbs(U, F).

% crafted_rar(U, F)
% FBS F responds with a fabricated RAR (Msg2, TS 38.321 §5.1.4) containing
% a synthetic Timing Advance, UL grant, and TC-RNTI.
% FBS subsequently drops Msg3 or continues the fake exchange — in both cases
% UE U cannot complete RRC Connection Setup.
% Corresponds to steps (ii)–(iii) of the FBS event sequence.
crafted_rar(U, F) :-
    fbs(F),
    rach_to_fbs(U, F).


% =========================================================================
% TIER D (FBS): FAILURE CONDITION
% =========================================================================

% preambletransmax_hit(U)
% UE U exhausts preambleTransMax retransmissions (TS 38.321 §5.1.2) without
% receiving a valid Msg4 (RRC Connection Setup Complete from FBS).
% preambleTransMax ∈ {3,4,5,6,7,8,10,20,50,100,200} per 3GPP.
preambletransmax_hit(U) :-
    rach_to_fbs(U, F),
    crafted_rar(U, F),
    rach_config(_, PMAX, _),
    PMAX > 0.


% =========================================================================
% TIER E (FBS): SECURITY IMPACT
% =========================================================================

% rach_failure_fbs(U)
% RACH procedure failed for UE U on the FBS path.
rach_failure_fbs(U) :-
    preambletransmax_hit(U).

% rrc_idle(U)
% UE U transitions to RRC_Idle (TS 38.331 §5.3.3) after RACH failure.
% UE obtains no legitimate service; it joins U_F(t) in the paper's notation.
% UE will subsequently search for another cell (may select same FBS again
% depending on deployment density — modelled in the simulation layer).
rrc_idle(U) :-
    rach_failure_fbs(U).


% =========================================================================
% TIER C: MUE ATTACK CHAIN — protocol-level exploit
% =========================================================================

% rach_slot_consumed(G)
% MUE M floods PRACH occasion slots at gNB G at rate R.
% When R ≥ N_OCC, all slots in that occasion are occupied by fake Msg1
% preambles, following the RACH occasion structure of TS 38.213 §8.1.
% Also directly derivable from observed high-contention data.
rach_slot_consumed(G) :-
    gnb(G), mue(M),
    mue_targets(M, G),
    prach_unprotected(G),
    flood_rate(M, R),
    rach_config(G, _, N_OCC),
    R >= N_OCC.

rach_slot_consumed(G) :-       % observed route: inferred from failure pattern
    high_contention_gnb(G).

% rach_contention(U, G)
% Benign UE U, correctly associated with legitimate gNB G, now shares RACH
% resources with MUE-injected preambles.
% Condition: UE is NOT at an FBS (enforces U_F ∩ U_G = ∅).
rach_contention(U, G) :-
    ue(U), gnb(G),
    observed_gnb_assoc(U, G),   % UE is at a legitimate gNB
    \+ ue_selects_fbs(U, _),    % UE not captured by any FBS
    rach_slot_consumed(G).


% =========================================================================
% TIER D (MUE): DEGRADATION STATE
% =========================================================================

% queueing_delay(U, G)
% RACH contention at gNB G increases scheduling delay for UE U.
% The gNB scheduler must resolve preamble collisions before serving
% legitimate UEs, introducing attachment latency (primary MUE impact).
queueing_delay(U, G) :-
    rach_contention(U, G).

% rach_failure_mue(U)
% Severe flooding: UE U exhausts preambleTransMax even at a legitimate gNB,
% triggering a retry cycle (secondary MUE impact).
rach_failure_mue(U) :-
    rach_contention(U, G),
    rach_config(G, PMAX, _),
    PMAX > 0.


% =========================================================================
% TIER E (MUE): SECURITY IMPACT
% =========================================================================

% service_degraded(U, G)
% Terminal MUE impact state: UE U at gNB G experiences elevated attachment
% delay (primary) or RACH failure and retry cycle (severe case).
% UE U remains in U_G(t) but with degraded quality of service.
service_degraded(U, G) :-
    queueing_delay(U, G).


% =========================================================================
% SYNERGY PREDICATE (TIER E — combined config only)
% Active exclusively when BOTH the FBS path and the MUE path are active.
% Encodes the λ_eff amplification mechanism (Equation 1 of the paper).
% =========================================================================

% lambda_eff_amplified(G)
% When FBS diverts UEs into U_F(t), |U_G(g_k,t)| shrinks while n_M(g_k)
% is unchanged.  Therefore:
%     λ_eff(g_k,t) = n_M(g_k) / |U_G(g_k,t)|  increases.
% Each remaining benign UE faces proportionally higher contention.
% The condition U \= V enforces U_F ∩ U_G = ∅ (the paper's partition).
lambda_eff_amplified(G) :-
    gnb(G),
    rrc_idle(U),               % FBS path active: at least one UE in U_F
    rach_contention(V, G),     % MUE path active at gNB G
    U \= V.                    % U_F and U_G are disjoint

% synergistic_impact(G)
% Terminal synergy state: combined attack at gNB G exceeds the sum of
% individual impacts.  This predicate is the formal grounding for the
% superadditivity result and corresponds to the dashed synergy edge in
% Figure~\ref{fig:attack_graph}.
synergistic_impact(G) :-
    lambda_eff_amplified(G).


% =========================================================================
% QUERY PREDICATES: collect all derived states for output
% =========================================================================

all_rrc_idle(UEs) :-
    findall(U, rrc_idle(U), Us),
    sort(Us, UEs).

all_queueing_delay(Pairs) :-
    findall(U-G, queueing_delay(U, G), Ps),
    sort(Ps, Pairs).

all_synergy(GNBs) :-
    findall(G, synergistic_impact(G), Gs),
    sort(Gs, GNBs).


% =========================================================================
% DOT GRAPH OUTPUT
% Writes attack_graph.dot in the current working directory.
% =========================================================================

write_dot :-
    open('attack_graph.dot', write, S),
    format(S, "digraph nr_attack_graph {\n", []),
    format(S, "  rankdir=TB;\n", []),
    format(S, "  node [shape=box, style=filled, fontname=Helvetica, fontsize=11];\n", []),
    format(S, "  edge [fontname=Helvetica, fontsize=9];\n\n", []),

    % ── Attacker tier ────────────────────────────────────────────────────
    ( fbs(_), mue(_) ->
        format(S, '  A_comb [label="FBS + MUE\\nCoordinated attack" fillcolor="#d8f5ec"];\n', [])
    ; fbs(_) ->
        format(S, '  A_fbs [label="FBS only\\nRogue base station" fillcolor="#fde8e0"];\n', [])
    ; mue(_) ->
        format(S, '  A_mue [label="MUE only\\nMalicious UE" fillcolor="#deeefe"];\n', [])
    ; true ),
    nl(S),

    % ── Tier B ───────────────────────────────────────────────────────────
    ( fbs(_) ->
        format(S, '  B_no_auth [label="SIB1 spoof\\nNo cell authentication" fillcolor="#f2f1ef"];\n', [])
    ; true ),
    ( mue(_) ->
        format(S, '  B_prach [label="Msg1 preamble flood\\nPRACH unprotected" fillcolor="#f2f1ef"];\n', [])
    ; true ),
    nl(S),

    % ── Tier C (FBS): ue_selects_fbs instances ───────────────────────────
    forall(ue_selects_fbs(U, F),
        format(S, '  C_sel_~w_~w [label="UE ~w selects FBS ~w\\nFake RACH exchange" fillcolor="#eee8fe"];\n',
               [U, F, U, F])),

    % ── Tier C (MUE): rach_slot_consumed instances ───────────────────────
    forall(rach_slot_consumed(G),
        format(S, '  C_slot_~w [label="RACH slots consumed\\ngNB ~w" fillcolor="#eee8fe"];\n',
               [G, G])),
    nl(S),

    % ── Tier D (FBS): preambletransmax_hit ───────────────────────────────
    forall(preambletransmax_hit(U),
        format(S, '  D_pmax_~w [label="preambleTransMax hit\\nUE ~w" fillcolor="#fef5d8"];\n',
               [U, U])),

    % ── Tier D (MUE): queueing_delay ─────────────────────────────────────
    forall(queueing_delay(U, G),
        format(S, '  D_qd_~w_~w [label="Queueing delay\\nUE ~w @ gNB ~w" fillcolor="#fef5d8"];\n',
               [U, G, U, G])),
    nl(S),

    % ── Tier E (FBS): rrc_idle ────────────────────────────────────────────
    forall(rrc_idle(U),
        format(S, '  E_idle_~w [label="RACH failure → RRC_Idle\\nU_F: UE ~w" fillcolor="#feeaea"];\n',
               [U, U])),

    % ── Tier E (MUE): service_degraded ───────────────────────────────────
    forall(service_degraded(U, G),
        format(S, '  E_deg_~w_~w [label="Service degraded\\nUE ~w @ gNB ~w" fillcolor="#feeaea"];\n',
               [U, G, U, G])),

    % ── Tier E (synergy) ─────────────────────────────────────────────────
    forall(synergistic_impact(G),
        format(S, '  E_syn_~w [label="Synergistic impact\\nlambda_eff amplified @ ~w" style="filled,dashed" fillcolor="#feeaea"];\n',
               [G, G])),
    nl(S),

    % ── Edges ─────────────────────────────────────────────────────────────
    ( fbs(_), mue(_) ->
        ( format(S, "  A_comb -> B_no_auth;\n", []),
          format(S, "  A_comb -> B_prach;\n",   []) )
    ; fbs(_) ->
        format(S, "  A_fbs -> B_no_auth;\n", [])
    ; mue(_) ->
        format(S, "  A_mue -> B_prach;\n", [])
    ; true ),

    forall(ue_selects_fbs(U, F),
        format(S, "  B_no_auth -> C_sel_~w_~w;\n", [U, F])),
    forall(rach_slot_consumed(G),
        format(S, "  B_prach -> C_slot_~w;\n", [G])),
    forall(preambletransmax_hit(U),
        ( ue_selects_fbs(U, F),
          format(S, "  C_sel_~w_~w -> D_pmax_~w;\n", [U, F, U]) )),
    forall(rrc_idle(U),
        format(S, "  D_pmax_~w -> E_idle_~w;\n", [U, U])),
    forall(rach_slot_consumed(G),
        forall(queueing_delay(U, G),
            format(S, "  C_slot_~w -> D_qd_~w_~w;\n", [G, U, G]))),
    forall(service_degraded(U, G),
        format(S, "  D_qd_~w_~w -> E_deg_~w_~w;\n", [U, G, U, G])),
    forall(synergistic_impact(G),
        ( rrc_idle(U), rach_contention(V, G), U \= V, !,
          format(S, '  E_idle_~w -> E_syn_~w [style=dashed label="lambda_eff amplified"];\n', [U, G]),
          format(S, '  E_deg_~w_~w -> E_syn_~w;\n', [V, G, G]) )),

    format(S, "}\n", []),
    close(S).


% =========================================================================
% MAIN ENTRY POINT
% =========================================================================

run_all :-
    format("=== NR Attack Graph Inference ===~n~n"),

    all_rrc_idle(IdleUEs),
    format("[FBS path]  rrc_idle UEs      : ~w~n", [IdleUEs]),

    all_queueing_delay(Delays),
    format("[MUE path]  queueing_delay    : ~w~n", [Delays]),

    all_synergy(SynGNBs),
    ( SynGNBs = [] ->
        format("[Synergy]   not active (single-attacker config)~n")
    ;
        format("[Synergy]   lambda_eff amplified at gNBs: ~w~n", [SynGNBs])
    ),

    % Derive config type from which attackers are present
    ( fbs(_), mue(_) -> Cfg = combined
    ; fbs(_)          -> Cfg = fbs_only
    ; mue(_)          -> Cfg = mue_only
    ;                    Cfg = benign ),
    format("~nConfig type : ~w~n", [Cfg]),
    format("Tiers reached: ~w~n~n",
           [[ tier_b_vuln,
              (IdleUEs \= [] -> tier_c_fbs_exploit ; skipped_fbs),
              (Delays  \= [] -> tier_c_mue_exploit ; skipped_mue),
              (IdleUEs \= [] -> tier_e_fbs_impact  ; skipped_fbs),
              (Delays  \= [] -> tier_e_mue_impact  ; skipped_mue),
              (SynGNBs \= [] -> tier_e_synergy     ; no_synergy) ]]),

    format("Writing DOT file …~n"),
    write_dot,
    format("Done. Output: attack_graph.dot~n").
